import numpy as np
import math

def generate(params, n, chip):
    # Parse and cast parameters
    core_r = int(float(params['core_r']))
    spiral_w = int(float(params['spiral_w']))
    spiral_turns = int(float(params['spiral_turns']))
    spiral_pitch = int(float(params['spiral_pitch']))
    angular_offset = float(params['angular_offset'])

    # Ensure minimum widths and turns
    spiral_w = max(2, spiral_w)
    spiral_turns = max(1, spiral_turns)
    spiral_pitch = max(2, spiral_pitch)
    core_r = max(0, core_r)

    i0, i1, j0, j1 = chip
    grid = np.zeros((n, n), dtype=bool)

    # Fill chip region
    grid[i0:i1+1, j0:j1+1] = True

    # Chip center
    cx = (i0 + i1) / 2.0
    cy = (j0 + j1) / 2.0

    # Solid circular core (radius in cells)
    if core_r > 0:
        for i in range(n):
            di = i - cx
            if di*di > core_r*core_r: 
                continue
            dj_limit = math.isqrt(core_r*core_r - int(di*di)) if di*di <= core_r*core_r else -1
            if dj_limit < 0: 
                continue
            j_min = max(0, int(math.floor(cy - dj_limit)))
            j_max = min(n-1, int(math.ceil(cy + dj_limit)))
            for j in range(j_min, j_max+1):
                grid[i, j] = True

    # Two counter-rotating spirals from opposite chip corners
    corners = [(i0, j0), (i1, j1)]  # top-left and bottom-right of chip
    for (sx, sy) in corners:
        theta = 0.0
        r = 0.0
        dtheta = 0.2  # angular step in radians
        pitch_per_rad = spiral_pitch / (2 * math.pi)  # radial increase per radian
        total_angle = 2 * math.pi * spiral_turns
        # Alternate rotation direction: first spiral CCW, second CW
        dir_sign = 1 if (sx, sy) == corners[0] else -1
        theta += dir_sign * angular_offset * math.pi / 2  # apply offset

        while theta <= total_angle:
            r = pitch_per_rad * theta
            x = sx + r * math.cos(theta)
            y = sy + r * math.sin(theta)

            # Perpendicular (normal) vector to tangent
            tx = -math.sin(theta)
            ty = math.cos(theta)
            nx = dir_sign * ty  # rotate tangent 90°: (-ty, tx) scaled by dir_sign for inward/outward normal
            ny = -dir_sign * tx

            hw = spiral_w / 2.0
            x_min = max(0, int(math.floor(x - hw)))
            x_max = min(n-1, int(math.ceil(x + hw)))
            y_min = max(0, int(math.floor(y - hw)))
            y_max = min(n-1, int(math.ceil(y + hw)))

            for i in range(x_min, x_max+1):
                for j in range(y_min, y_max+1):
                    vx = i - x
                    vy = j - y
                    dist_normal = abs(vx * nx + vy * ny)
                    if dist_normal <= hw + 1e-5:
                        grid[i, j] = True

            theta += dtheta

    # Ensure 4-connectivity to chip by growing from chip
    changed = True
    while changed:
        changed = False
        for i in range(n):
            for j in range(n):
                if grid[i, j]:
                    for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = i+di, j+dj
                        if 0 <= ni < n and 0 <= nj < n and not grid[ni, nj]:
                            grid[ni, nj] = True
                            changed = True

    # Remove material not connected to chip (BFS from chip)
    visited = np.zeros((n, n), dtype=bool)
    queue = []
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            if grid[i, j]:
                visited[i, j] = True
                queue.append((i, j))
    while queue:
        i, j = queue.pop(0)
        for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < n and grid[ni, nj] and not visited[ni, nj]:
                visited[ni, nj] = True
                queue.append((ni, nj))
    grid = grid & visited

    # Enforce minimum feature size: 2 cells wide
    # Remove any cell that would leave a neighbor with <2 adjacent in either axis if removed
    # We do: a cell is safe to keep only if it has at least 2 neighbors in some direction (not just count)
    # Instead: ensure no 1-cell protrusions by checking that every material cell has
    # at least one adjacent pair in x or y direction (i.e., part of a 2-cell segment)
    def has_min_width(i, j):
        # Check horizontal: at least two consecutive in row
        if j-1 >= 0 and grid[i, j-1] and (j+1 < n and grid[i, j+1]):
            return True
        if j-1 >= 0 and grid[i, j-1] and (j-2 >= 0 and grid[i, j-2]):
            return True
        if j+1 < n and grid[i, j+1] and (j+2 < n and grid[i, j+2]):
            return True
        # Check vertical
        if i-1 >= 0 and grid[i-1, j] and (i+1 < n and grid[i+1, j]):
            return True
        if i-1 >= 0 and grid[i-1, j] and (i-2 >= 0 and grid[i-2, j]):
            return True
        if i+1 < n and grid[i+1, j] and (i+2 < n and grid[i+2, j]):
            return True
        return False

    # Iteratively remove violators until stable
    changed = True
    while changed:
        changed = False
        to_remove = []
        for i in range(n):
            for j in range(n):
                if grid[i, j] and not has_min_width(i, j):
                    to_remove.append((i, j))
        for i, j in to_remove:
            grid[i, j] = False
            changed = True

    # Re-ensure connectivity after width enforcement
    changed = True
    while changed:
        changed = False
        for i in range(n):
            for j in range(n):
                if grid[i, j]:
                    for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = i+di, j+dj
                        if 0 <= ni < n and 0 <= nj < n and not grid[ni, nj]:
                            grid[ni, nj] = True
                            changed = True

    # Final connectivity cleanup (keep only chip-connected)
    visited = np.zeros((n, n), dtype=bool)
    queue = []
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            if grid[i, j]:
                visited[i, j] = True
                queue.append((i, j))
    while queue:
        i, j = queue.pop(0)
        for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < n and grid[ni, nj] and not visited[ni, nj]:
                visited[ni, nj] = True
                queue.append((ni, nj))
    grid = grid & visited

    # Enforce cell budget: at most 1440
    current_count = np.sum(grid)
    if current_count > 1440:
        # Compute approximate distance from chip (Manhattan via BFS)
        dist = np.full((n, n), -1, dtype=int)
        queue = []
        for i in range(i0, i1+1):
            for j in range(j0, j1+1):
                dist[i, j] = 0
                queue.append((i, j))
        while queue:
            i, j = queue.pop(0)
            for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < n and 0 <= nj < n and dist[ni, nj] == -1:
                    dist[ni, nj] = dist[i, j] + 1
                    queue.append((ni, nj))
        # Collect material cells with distance
        cells = []
        for i in range(n):
            for j in range(n):
                if grid[i, j] and dist[i, j] != -1:
                    cells.append((dist[i, j], i, j))
        # Sort farthest first
        cells.sort(key=lambda x: x[0], reverse=True)
        to_remove = current_count - 1440
        for idx in range(min(to_remove, len(cells))):
            _, i, j = cells[idx]
            grid[i, j] = False
        # Final connectivity repair
        changed = True
        while changed:
            changed = False
            for i in range(n):
                for j in range(n):
                    if grid[i, j]:
                        for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                            ni, nj = i+di, j+dj
                            if 0 <= ni < n and 0 <= nj < n and not grid[ni, nj]:
                                grid[ni, nj] = True
                                changed = True
        visited = np.zeros((n, n), dtype=bool)
        queue = []
        for i in range(i0, i1+1):
            for j in range(j0, j1+1):
                if grid[i, j]:
                    visited[i, j] = True
                    queue.append((i, j))
        while queue:
            i, j = queue.pop(0)
            for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < n and 0 <= nj < n and grid[ni, nj] and not visited[ni, nj]:
                    visited[ni, nj] = True
                    queue.append((ni, nj))
        grid = grid & visited

    return grid
